"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { CircleCheckIcon, GlobeIcon } from "../parts/icons";
import { ATTENDEES, formatClock, MEETING_MINUTES, openCount, PICKER_DAYS, SLOT_STARTS } from "./availability-picker/data";
import { SlotOption } from "./availability-picker/slot-option";
import { AvatarStack } from "./shared/avatar";
import { ClockIcon } from "./shared/icons";
import { person } from "./shared/people";
import { useRoving } from "./shared/use-roving";

/**
 * Picks a meeting time that suits four people. Choose a day by its open-slot
 * count, then a slot: each one says who is free. The slots slide in from the
 * side of the day you moved to, and the highlight glides between slots.
 */
export function AvailabilityPicker({ className }: { className?: string }) {
  const [dayIndex, setDayIndex] = useState(2);
  const [direction, setDirection] = useState(1);
  const [slotIndex, setSlotIndex] = useState(0);
  const [confirmed, setConfirmed] = useState<string | null>(null);
  const reduceMotion = useReducedMotion();
  const titleId = useId();
  const highlightId = useId();

  const day = PICKER_DAYS[dayIndex]!;
  const start = SLOT_STARTS[slotIndex]!;
  const busy = day.busy[slotIndex] ?? [];

  const pickDay = (index: number) => {
    if (index === dayIndex) return;
    setDirection(index > dayIndex ? 1 : -1);
    setDayIndex(index);
    const firstOpen = PICKER_DAYS[index]!.busy.findIndex((list) => list.length === 0);
    setSlotIndex(Math.max(0, firstOpen));
    setConfirmed(null);
  };

  const pickSlot = (index: number) => {
    setSlotIndex(index);
    setConfirmed(null);
  };

  const days = useRoving(PICKER_DAYS.length, dayIndex, pickDay);
  const slots = useRoving(SLOT_STARTS.length, slotIndex, pickSlot);
  const chosen = `${day.weekday}, ${day.date}, ${formatClock(start)} to ${formatClock(start + MEETING_MINUTES)}`;

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("max-w-2xl", className)}>
      <header className="flex flex-wrap items-start justify-between gap-3 border-b border-border px-5 py-4">
        <div className="flex min-w-0 flex-col gap-1">
          <h2 id={titleId} className="text-base font-semibold">
            Treatment plan review
          </h2>
          <p className="flex flex-wrap items-center gap-x-4 gap-y-1 text-sm text-muted-foreground">
            <span className="flex items-center gap-1.5">
              <ClockIcon aria-hidden="true" className="size-4" />
              {MEETING_MINUTES} minutes
            </span>
            <span className="flex items-center gap-1.5">
              <GlobeIcon aria-hidden="true" className="size-4" />
              London time
            </span>
          </p>
        </div>
        <AvatarStack people={ATTENDEES.map(person)} size="md" />
      </header>

      <div role="radiogroup" aria-label="Day" className="grid grid-cols-5 gap-1.5 px-4 pt-4">
        {PICKER_DAYS.map((item, index) => {
          const checked = index === dayIndex;
          const open = openCount(item);
          return (
            <div
              key={item.id}
              role="radio"
              aria-checked={checked}
              aria-label={`${item.weekday}, ${item.date}, ${open} open ${open === 1 ? "slot" : "slots"}`}
              onClick={() => pickDay(index)}
              {...days.itemProps(index)}
              className={cn(
                "group relative isolate flex cursor-pointer flex-col items-center gap-0.5 rounded-xl border px-1 py-2 text-center outline-none focus-visible:ring-2 focus-visible:ring-ring",
                checked ? "border-chart-1" : "border-border",
              )}
            >
              <span aria-hidden="true" className={cn("absolute inset-0 -z-10 rounded-xl", checked ? "bg-muted/60" : "group-hover:bg-muted/40")} />
              <span className="text-xs text-muted-foreground">{item.weekday.slice(0, 3)}</span>
              <span className="text-sm font-semibold">{item.date.split(" ")[1]}</span>
              <span className={cn("text-xs tabular-nums", open > 0 ? "text-marketing-green-ink" : "text-muted-foreground")}>
                {open} open
              </span>
            </div>
          );
        })}
      </div>

      <div className="flex flex-wrap items-center justify-between gap-2 px-5 pt-4 pb-1">
        <h3 className="text-sm font-medium">
          {day.weekday}, {day.date}
        </h3>
        <span aria-hidden="true" className="flex items-center gap-3 text-xs text-muted-foreground">
          <span className="flex items-center gap-1.5">
            <span className="h-3 w-1.5 rounded-full bg-chart-2" />
            Free
          </span>
          <span className="flex items-center gap-1.5">
            <span className="h-3 w-1.5 rounded-full border border-muted-foreground/60" />
            Busy
          </span>
        </span>
      </div>

      <div className="relative overflow-hidden px-2 pb-3">
        <AnimatePresence mode="popLayout" initial={false} custom={direction}>
          <motion.div
            key={day.id}
            role="radiogroup"
            aria-label={`Times on ${day.weekday}`}
            custom={direction}
            initial={reduceMotion ? { opacity: 0 } : { x: `${direction * 30}%`, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={reduceMotion ? { opacity: 0 } : { x: `${direction * -30}%`, opacity: 0 }}
            transition={reduceMotion ? { duration: 0.15 } : { type: "spring", stiffness: 380, damping: 38 }}
            className="grid gap-0.5 @2xl:grid-cols-2"
          >
            {SLOT_STARTS.map((slot, index) => (
              <SlotOption
                key={slot}
                start={slot}
                busy={day.busy[index] ?? []}
                checked={index === slotIndex}
                onSelect={() => pickSlot(index)}
                layoutId={`${highlightId}-${day.id}`}
                roving={slots.itemProps(index)}
              />
            ))}
          </motion.div>
        </AnimatePresence>
      </div>

      <footer className="flex flex-wrap items-center justify-between gap-3 border-t border-border px-5 py-3">
        <p className="flex min-w-0 items-center gap-2 text-sm" role="status">
          {confirmed ? <CircleCheckIcon aria-hidden="true" className="size-4 shrink-0 text-marketing-green-ink" /> : null}
          <span className="min-w-0">
            {confirmed ? `Invites sent for ${confirmed}` : chosen}
            {!confirmed && busy.length > 0 ? (
              <span className="block text-xs text-muted-foreground">
                {busy.length} of {ATTENDEES.length} people would miss it
              </span>
            ) : null}
          </span>
        </p>
        <Button onClick={() => setConfirmed(chosen)} disabled={confirmed !== null}>
          {confirmed ? "Confirmed" : "Confirm time"}
        </Button>
      </footer>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

