/** One day the meeting can fall on. */
export interface PickerDay {
  id: string;
  weekday: string;
  date: string;
  /** For each slot, the ids of the attendees who are busy then. */
  busy: string[][];
}

/** The people invited to the meeting, by team id. */
export const ATTENDEES = ["ines", "noor", "kofi", "lena"];

/** The start of each 45-minute slot, in minutes after midnight. */
export const SLOT_STARTS = [540, 600, 660, 720, 810, 870, 930, 990];

/** The meeting length, in minutes. */
export const MEETING_MINUTES = 45;

const DAY_NAMES: [string, string][] = [
  ["Monday", "Nov 16"],
  ["Tuesday", "Nov 17"],
  ["Wednesday", "Nov 18"],
  ["Thursday", "Nov 19"],
  ["Friday", "Nov 20"],
];

// A fixed pattern per day, so every render shows the same calendar. Each
// string lists one letter per slot: the initial of whoever is busy, or "-".
const BUSY_PATTERN = [
  ["IN", "-", "K", "KL", "-", "N", "-", "IL"],
  ["NKL", "IK", "IKL", "N", "INK", "L", "IN", "K"],
  ["-", "L", "-", "IN", "K", "-", "L", "-"],
  ["K", "INL", "I", "-", "NL", "KL", "INK", "L"],
  ["L", "-", "NK", "INKL", "I", "-", "K", "N"],
];

const LETTER = new Map([
  ["I", "ines"],
  ["N", "noor"],
  ["K", "kofi"],
  ["L", "lena"],
]);

/** The five sample days, Monday to Friday of next week. */
export const PICKER_DAYS: PickerDay[] = DAY_NAMES.map(([weekday, date], index) => ({
  id: weekday.toLowerCase(),
  weekday,
  date,
  busy: (BUSY_PATTERN[index] ?? []).map((code) => (code === "-" ? [] : [...code].map((letter) => LETTER.get(letter) ?? ""))),
}));

const TIME = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit", timeZone: "UTC" });

/** A time of day, such as 9:45 AM, from minutes after midnight. */
export const formatClock = (minutes: number) => TIME.format(new Date(Date.UTC(2026, 10, 16, 0, minutes)));

/** How many slots on a day have every attendee free. */
export const openCount = (day: PickerDay) => day.busy.filter((list) => list.length === 0).length;

"use client";

import { motion, useReducedMotion } from "motion/react";
import type { KeyboardEvent } from "react";

import { cn } from "@/lib/utils";

import { HUE_FILL, person } from "../shared/people";
import { ATTENDEES, formatClock, MEETING_MINUTES } from "./data";

/** Props for one time slot in the picker. */
export interface SlotOptionProps {
  start: number;
  busy: string[];
  checked: boolean;
  onSelect: () => void;
  /** Shared by every slot in one picker, so the highlight glides from slot to slot. */
  layoutId: string;
  roving: { ref: (node: HTMLElement | null) => void; tabIndex: number; onKeyDown: (event: KeyboardEvent) => void };
}

/**
 * One time slot as a radio: the time, who is free, and one small bar per
 * attendee, solid in their hue when free and hollow when busy. The words carry
 * the same facts as the bars.
 */
export function SlotOption({ start, busy, checked, onSelect, layoutId, roving }: SlotOptionProps) {
  const reduceMotion = useReducedMotion();
  const free = ATTENDEES.length - busy.length;
  const who =
    busy.length === 0
      ? "Everyone is free"
      : `${busy.map((id) => person(id).name.split(" ")[0]).join(" and ")} ${busy.length === 1 ? "is" : "are"} busy`;
  return (
    <div
      role="radio"
      aria-checked={checked}
      aria-label={`${formatClock(start)} to ${formatClock(start + MEETING_MINUTES)}. ${who}.`}
      onClick={onSelect}
      {...roving}
      className="group relative isolate flex cursor-pointer items-center gap-3 rounded-xl px-3 py-2.5 outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      {checked ? (
        <motion.span
          layoutId={layoutId}
          aria-hidden="true"
          transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 40 }}
          className="absolute inset-0 -z-10 rounded-xl border border-chart-1 bg-muted/60"
        />
      ) : (
        <span aria-hidden="true" className="absolute inset-0 -z-10 rounded-xl group-hover:bg-muted/40" />
      )}
      <span className="w-40 shrink-0 text-sm font-medium whitespace-nowrap tabular-nums">
        {formatClock(start)} to {formatClock(start + MEETING_MINUTES)}
      </span>
      <span className={cn("min-w-0 flex-1 truncate text-xs", busy.length === 0 ? "text-marketing-green-ink" : "text-muted-foreground")}>
        {busy.length === 0 ? "Everyone free" : `${free} of ${ATTENDEES.length} free`}
      </span>
      <span aria-hidden="true" className="flex items-end gap-1">
        {ATTENDEES.map((id) => {
          const member = person(id);
          const isBusy = busy.includes(id);
          return (
            <span
              key={id}
              title={`${member.name}: ${isBusy ? "busy" : "free"}`}
              className={cn(
                "h-4 w-1.5 rounded-full",
                isBusy ? "border border-muted-foreground/60" : HUE_FILL[member.hue],
              )}
            />
          );
        })}
      </span>
    </div>
  );
}

/** The five chart hues, in order. A person or a calendar takes one by index. */
export type Hue = 1 | 2 | 3 | 4 | 5;

/** One member of the Fernhill team, used across the project blocks. */
export interface Person {
  id: string;
  name: string;
  initials: string;
  hue: Hue;
}

/** The Fernhill team. Every block draws its owners, attendees and authors from this list. */
export const TEAM: Person[] = [
  { id: "ines", name: "Ines Varga", initials: "IV", hue: 1 },
  { id: "tomas", name: "Tomas Reyes", initials: "TR", hue: 2 },
  { id: "noor", name: "Noor Haddad", initials: "NH", hue: 3 },
  { id: "kofi", name: "Kofi Mensah", initials: "KM", hue: 4 },
  { id: "lena", name: "Lena Brandt", initials: "LB", hue: 5 },
  { id: "arjun", name: "Arjun Patel", initials: "AP", hue: 2 },
];

/** The person with this id. Unknown ids fall back to the first person, so sample data never renders blank. */
export function person(id: string): Person {
  return TEAM.find((member) => member.id === id) ?? TEAM[0]!;
}

/** A solid fill in each hue, for a bar, a dot or a marker. Written out so the class lint can read every name. */
export const HUE_FILL = {
  1: "bg-chart-1",
  2: "bg-chart-2",
  3: "bg-chart-3",
  4: "bg-chart-4",
  5: "bg-chart-5",
} satisfies Record<Hue, string>;

/** A border in each hue. */
export const HUE_BORDER = {
  1: "border-chart-1",
  2: "border-chart-2",
  3: "border-chart-3",
  4: "border-chart-4",
  5: "border-chart-5",
} satisfies Record<Hue, string>;

/** Text in each hue, for an icon or a small mark. Not for body text: a hue may not reach 4.5 to 1. */
export const HUE_TEXT = {
  1: "text-chart-1",
  2: "text-chart-2",
  3: "text-chart-3",
  4: "text-chart-4",
  5: "text-chart-5",
} satisfies Record<Hue, string>;

import { cn } from "@/lib/utils";

import { HUE_BORDER, HUE_FILL, type Person } from "./people";

/** Props for one person's initials badge. */
export interface PersonAvatarProps {
  person: Person;
  /** `sm` is 1.5rem, `md` is 2rem. */
  size?: "sm" | "md";
  /** Shows the name to screen readers. Leave it off when the name is already written beside the badge. */
  labelled?: boolean;
  className?: string;
}

/**
 * A round badge with a person's initials, ringed and tinted in their hue. The
 * tint is a faded layer behind the letters, so the letters keep full contrast.
 */
export function PersonAvatar({ person, size = "sm", labelled = false, className }: PersonAvatarProps) {
  return (
    <span
      role={labelled ? "img" : undefined}
      aria-label={labelled ? person.name : undefined}
      aria-hidden={labelled ? undefined : true}
      title={person.name}
      className={cn(
        "relative isolate inline-grid shrink-0 place-items-center overflow-hidden rounded-full border-2 bg-card font-semibold text-foreground",
        HUE_BORDER[person.hue],
        size === "sm" ? "size-7 text-xs tracking-tight" : "size-8 text-xs",
        className,
      )}
    >
      <span aria-hidden="true" className={cn("absolute inset-0 -z-10 opacity-25", HUE_FILL[person.hue])} />
      {person.initials}
    </span>
  );
}

/** Props for a row of overlapping initials badges. */
export interface AvatarStackProps {
  people: Person[];
  /** Badges past this count fold into a "+N" badge. */
  max?: number;
  size?: "sm" | "md";
  className?: string;
}

/** A row of overlapping initials badges, named as one group, such as the people on a project. */
export function AvatarStack({ people, max = 4, size = "sm", className }: AvatarStackProps) {
  const shown = people.slice(0, max);
  const rest = people.length - shown.length;
  return (
    <span
      role="img"
      aria-label={people.map((member) => member.name).join(", ")}
      className={cn("flex items-center -space-x-1.5", className)}
    >
      {shown.map((member) => (
        <PersonAvatar key={member.id} person={member} size={size} className="ring-2 ring-card" />
      ))}
      {rest > 0 ? (
        <span
          aria-hidden="true"
          className={cn(
            "inline-grid shrink-0 place-items-center rounded-full border-2 border-border bg-card font-medium text-muted-foreground ring-2 ring-card",
            size === "sm" ? "size-7 text-xs tracking-tight" : "size-8 text-xs",
          )}
        >
          +{rest}
        </span>
      ) : null}
    </span>
  );
}

